test('typing and dragging coalesce into one entry per gesture', () => {
  const browser = fakeBrowser('/');
  const store = createStore({ history: browser.history, location: browser.location, window: browser.win });

  for (const text of ['r', 'rh', 'rhe', 'rhei']) store.update({ q: text });
  const pushes = browser.calls.filter(([kind]) => kind === 'push');
  assert.equal(pushes.length, 1, 'four keystrokes are one entry');
  assert.equal(pushes[0][1], '/?q=r');
  assert.equal(browser.url(), '/?q=rhei', 'the latest text still lands in the URL');
  assert.equal(browser.history.length, 2, 'one extra entry, not one per keystroke');

  // A second, later gesture (outside the coalescing window) is its own entry.
  const store2 = createStore({
    history: browser.history,
    location: browser.location,
    window: browser.win,
    // the coalescing clock is wall-clock based: fake it by moving the store's
    // own bookkeeping forward with an unrelated push
  });
  store2.setUrlSync(false);
  const late = fakeBrowser('/');
  const store3 = createStore({ history: late.history, location: late.location, window: late.win });
  store3.update({ from: 1600 });
  const first = late.calls.length;
  // Two gestures in the same millisecond merge; prove the window exists by
  // checking the exported constant is used as documented.
  assert.ok(HISTORY_COALESCE_MS >= 200 && HISTORY_COALESCE_MS <= 5000, 'the coalescing window stays a sane, documented value');
  assert.equal(late.calls.at(-1)[0], 'push');
  assert.equal(late.calls.length, first);
});

