edits.newText:
await cdp.eval(`window.scrollTo({ top: 0, behavior: 'instant' }); true`);

/* --- 8l. browser back/forward walk the exploration -------------------- */
// The product promises shareable state, so the browser buttons have to walk
// the same path the user took: a selection or a search is a history entry,
// while panning the map and typing must not flood the history. The checks
// read behaviour (where does one press of “back” land?), not history.length,
// which browsers clamp.
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });

// 8l-1: leaving the app and coming back must not be blocked by entries the
// app creates while it is starting up (its year range is clamped to the data).
await cdp.send('Page.navigate', { url: 'about:blank' });
await cdp.waitFor(`location.href === 'about:blank'`, { label: 'blank page', timeout: 10_000 });
await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'history start page' });
await sleep(1500); // give any late start-up write-back time to happen
await cdp.eval(`history.back()`).catch(() => {});
let backToPreviousSite = false;
try {
  backToPreviousSite = await cdp.waitFor(`location.href === 'about:blank' ? 'yes' : ''`, { label: 'one back press leaves the app', timeout: 8_000 });
} catch {
  /* reported below */
}
check(
  'the app adds no history entry of its own while it starts up',
  backToPreviousSite === 'yes',
  `after one “back”: ${JSON.stringify(await cdp.eval(`location.href`).catch(() => '?'))}`,
);

// 8l-2: forward restores the app, and it still works (bfcache or reload).
await cdp.eval(`history.forward()`).catch(() => {});
let forwardWorks = false;
try {
  forwardWorks = await cdp.waitFor(
    `document.querySelectorAll('#result-list > *').length > 5 ? { rows: document.querySelectorAll('#result-list > *').length, url: location.search } : ''`,
    { label: 'forward returns to the app', timeout: 10_000 },
  );
} catch {
  /* reported below */
}
check('“forward” brings the app back with its results', Boolean(forwardWorks?.rows > 5), JSON.stringify(forwardWorks));

// 8l-3: opening a record is a history entry; “back” closes it again.
const historyRecord = recordIndex.size > 0 ? [...recordIndex.values()].find((r) => r.title) : null;
let opened = null;
if (historyRecord) {
  await cdp.click(`#result-list button[data-record-id="${historyRecord.id}"]`).catch(() => {});
  try {
    opened = await cdp.waitFor(
      `(() => {
        const sel = new URLSearchParams(location.search).get('sel');
        const panel = document.querySelector('#detail');
        return sel && panel && panel.hidden === false ? { sel, open: true } : '';
      })()`,
      { label: 'record opened for the history check', timeout: 12_000 },
    );
  } catch {
    /* reported below */
  }
}
check(
  'opening a record is a step the browser can undo',
  Boolean(opened?.open) && opened?.sel === historyRecord?.id,
  opened ? `sel=${opened.sel}` : 'the detail panel never opened',
);

await cdp.eval(`history.back()`).catch(() => {});
let afterBack = null;
try {
  afterBack = await cdp.waitFor(
    `(() => {
      const sel = new URLSearchParams(location.search).get('sel');
      const panel = document.querySelector('#detail');
      return !sel && panel && panel.hidden === true ? { sel: sel || null, rows: document.querySelectorAll('#result-list > *').length } : '';
    })()`,
    { label: 'back closes the record', timeout: 12_000 },
  );
} catch {
  /* reported below */
}
check(
  '“back” closes the open record and keeps the search',
  afterBack !== null && afterBack.rows > 5,
  JSON.stringify(afterBack ?? { url: await cdp.eval(`location.search`).catch(() => '?') }),
);

// 8l-4: “forward” re-opens it.
await cdp.eval(`history.forward()`).catch(() => {});
let afterForward = null;
try {
  afterForward = await cdp.waitFor(
    `(() => {
      const sel = new URLSearchParams(location.search).get('sel');
      return sel ? { sel, open: document.querySelector('#detail')?.hidden === false } : '';
    })()`,
    { label: 'forward re-opens the record', timeout: 12_000 },
  );
} catch {
  /* reported below */
}
check('“forward” re-opens the record', afterForward?.sel === historyRecord?.id && afterForward?.open === true, JSON.stringify(afterForward));

// 8l-5: panning the map and typing a search must not each become entries:
// one press of “back” has to remove the whole gesture.
const dragBox = await cdp
  .eval(`(() => { const m = document.querySelector('.app-map'); if (!m) return null; const r = m.getBoundingClientRect(); return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) }; })()`)
  .catch(() => null);
if (dragBox) {
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: dragBox.x, y: dragBox.y });
  await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: dragBox.x, y: dragBox.y, button: 'left', clickCount: 1 });
  for (const step of [40, 80, 120, 160]) {
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: dragBox.x + step, y: dragBox.y + step / 2, button: 'left' });
    await sleep(60);
  }
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: dragBox.x + 160, y: dragBox.y + 80, button: 'left', clickCount: 1 });
  await sleep(900);
}
const panned = await cdp.eval(`({ lat: new URLSearchParams(location.search).get('lat'), sel: new URLSearchParams(location.search).get('sel') })`);
await cdp.eval(`document.querySelector('#detail-close')?.click(); true`);
await sleep(400);
await cdp.eval(`history.back()`).catch(() => {});
await sleep(1500);
const afterPanBack = await cdp.eval(`({ search: location.search, rows: document.querySelectorAll('#result-list > *').length })`);
check(
  'a map drag replaces the entry instead of adding history steps',
  Boolean(panned.lat) && afterPanBack.rows > 5 && !afterPanBack.search.includes('sel='),
  `pan wrote lat=${panned.lat} · after one “back”: ${afterPanBack.search || '(no query)'} with ${afterPanBack.rows} rows`,
);

// 8l-6: a typed search is one entry, not one per keystroke.
await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 5`, { label: 'typing history page' });
await sleep(600);
await cdp.typeInto('#filter-text', 'Rhein');
await sleep(1200);
const typed = await cdp.eval(`({ q: new URLSearchParams(location.search).get('q'), rows: document.querySelectorAll('#result-list > *').length })`);
await cdp.eval(`history.back()`).catch(() => {});
await sleep(1500);
const afterTypeBack = await cdp.eval(`({ q: new URLSearchParams(location.search).get('q'), rows: document.querySelectorAll('#result-list > *').length })`);
check(
  'one “back” undoes a whole typed search (keystrokes coalesce)',
  typed.q === 'Rhein' && afterTypeBack.q === null && afterTypeBack.rows > typed.rows && afterTypeBack.rows > 5,
  `typed “Rhein” -> ${typed.rows} rows, one “back” -> ${afterTypeBack.rows} rows, q=${JSON.stringify(afterTypeBack.q)}`,
);

// (the series section runs after 8j and opens another record of the seed)
/* --- console hygiene -------------------------------------------------- */

