/**
 * Diagnostic: log every history write and popstate around a select + back.
 */
import { launch, sleep } from './cdp.mjs';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const { cdp, close } = await launch({ port: 9346 });

const LOGGER = `(() => {
  if (window.__histLog) return 'already';
  const log = [];
  window.__histLog = log;
  const t0 = performance.now();
  const stamp = () => Math.round(performance.now() - t0);
  for (const kind of ['pushState', 'replaceState']) {
    const original = history[kind].bind(history);
    history[kind] = (state, title, url) => {
      log.push([stamp(), kind, String(url), { lat: state && state.lat, sel: state && state.selected, q: state && state.q }]);
      return original(state, title, url);
    };
  }
  addEventListener('popstate', () => log.push([stamp(), 'popstate', location.pathname + location.search]));
  addEventListener('click', () => log.push([stamp(), 'click']), true);
  addEventListener('pointerdown', () => log.push([stamp(), 'pointerdown']), true);
  return 'ok';
})()`;

try {
  await cdp.goto(BASE + '/');
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 5`, { label: 'results' });
  await sleep(1200);
  console.log('logger:', await cdp.eval(LOGGER));

  const id = await cdp.eval(`document.querySelector('#result-list button[data-record-id]')?.dataset.recordId`);
  await cdp.click(`#result-list button[data-record-id="${id}"]`);
  await sleep(2000);
  console.log('after click url:', await cdp.eval(`location.search`));
  await cdp.eval(`history.back()`);
  await sleep(2500);
  console.log('after back url :', await cdp.eval(`location.search`));
  await sleep(1500);
  console.log('after settle   :', await cdp.eval(`location.search`));
  const log = await cdp.eval(`window.__histLog`);
  for (const row of log) console.log(row[0].toString().padStart(7), row[1].padEnd(13), row[2], JSON.stringify(row[3] ?? ''));
} finally {
  await close();
}

