function close() {
  if (panel.hidden) return;
  viewer?.destroy();
  viewer = null;
  page = 0;
  // A closed panel must not leave a sheet number behind in the shared URL.
  if (ctx.store.getState().sheet !== 1) ctx.store.update({ sheet: 1 });
  panel.hidden = true;
  if (scrim) scrim.hidden = true;
  panel.setAttribute('aria-modal', 'false');
  document.body.classList.remove('has-detail');
  current = null;
  body.replaceChildren();
  opener?.focus?.();
  opener = null;
  // The selection is URL state (coordination D4): a closed panel must not stay
  // named by `?sel=`, or a reload would open a panel the user just dismissed
  // and the “back” button would have nothing to undo. The DOM is already torn
  // down here, so the subscribers this wakes up see a closed panel.
  if (ctx.store.getState().selected) ctx.store.update({ selected: '' });
  ctx.bus.emit('record:deselected', {});
}

