/**
 * Diagnostic: who removes ?sel= from the URL on a deep link?
 */
import { launch, sleep } from './cdp.mjs';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const { cdp, close } = await launch({ port: 9347 });

try {
  await cdp.goto(BASE + '/');
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 3`, { label: 'results' });
  const id = await cdp.eval(`document.querySelector('#result-list button[data-record-id]')?.dataset.recordId`);
  console.log('target record:', id);

  await cdp.send('Page.addScriptToEvaluateOnNewDocument', {
    source: `(() => {
      window.__log = [];
      const t0 = performance.now();
      const s = () => Math.round(performance.now() - t0);
      for (const kind of ['pushState', 'replaceState']) {
        const original = history[kind].bind(history);
        history[kind] = (state, title, url) => {
          window.__log.push([s(), kind, String(url), (new Error('x').stack || '').split('\\n').slice(1, 4).join(' <- ').replace(/https?:\\/\\/[^ )]*\\//g, '')]);
          return original(state, title, url);
        };
      }
      addEventListener('popstate', () => window.__log.push([s(), 'popstate', location.search, '']));
      addEventListener('DOMContentLoaded', () => window.__log.push([s(), 'DOMContentLoaded', location.search, '']));
    })()`,
  });
  await cdp.send('Page.navigate', { url: `${BASE}/?to=1850&sel=${encodeURIComponent(id)}` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'deep link results' });
  await sleep(2500);
  console.log('panelOpen:', await cdp.eval(`document.querySelector('#detail')?.hidden === false`));
  console.log('url      :', await cdp.eval(`location.search`));
  for (const row of await cdp.eval(`window.__log`)) {
    console.log(String(row[0]).padStart(6), row[1].padEnd(14), String(row[2]).slice(0, 70), '|', String(row[3]).slice(0, 200));
  }
} finally {
  await close();
}

