/**
 * Does pressing "back" after opening a record restore the page's scroll position?
 */
import { launch, sleep } from './cdp.mjs';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const { cdp, close } = await launch({ port: 9348, width: 1440, height: 900 });

const snap = () => cdp.eval(`({
  y: Math.round(window.scrollY),
  sel: new URLSearchParams(location.search).get('sel'),
  panel: document.querySelector('#detail')?.hidden === false,
  active: document.activeElement?.id || document.activeElement?.tagName,
})`);

try {
  await cdp.goto(BASE + '/');
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 5`, { label: 'results' });
  await sleep(1000);

  // scroll down so the list rows are visible on screen (desktop: sidebar)
  await cdp.eval(`window.scrollTo({ top: 900, behavior: 'instant' }); true`);
  await sleep(400);
  console.log('before     ', await snap());

  const id = await cdp.eval(`(() => {
    const buttons = [...document.querySelectorAll('#result-list button[data-record-id]')];
    const box = buttons.map((b) => b.getBoundingClientRect().top).findIndex((t) => t > 0 && t < window.innerHeight);
    const button = buttons[Math.max(0, box)];
    button.scrollIntoView({ block: 'center', behavior: 'instant' });
    return button.dataset.recordId;
  })()`);
  await cdp.click(`#result-list button[data-record-id="${id}"]`);
  await sleep(1500);
  console.log('after click', await snap());

  await cdp.eval(`history.back()`).catch(() => {});
  await sleep(2000);
  console.log('after back ', await snap());
} finally {
  await close();
}

