/**
 * Measure the intro “facts” strip at phone widths.
 */
import { launch, sleep } from './cdp.mjs';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const { cdp, close } = await launch({ port: 9349 });

const MEASURE = `(() => {
  const ul = document.querySelector('#intro-facts');
  if (!ul) return { missing: true };
  const items = [...ul.children].map((li) => {
    const r = li.getBoundingClientRect();
    return { term: li.textContent.trim().slice(0, 40), left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width) };
  });
  const cs = getComputedStyle(ul);
  const box = ul.getBoundingClientRect();
  return {
    box: { left: Math.round(box.left), right: Math.round(box.right), w: Math.round(box.width), h: Math.round(box.height) },
    scrollW: ul.scrollWidth,
    clientW: ul.clientWidth,
    overflowX: cs.overflowX,
    gap: cs.columnGap || cs.gap,
    fontSize: cs.fontSize,
    items,
    pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
  };
})()`;

try {
  for (const [w, h, mobile] of [[320, 640, true], [390, 844, true], [480, 800, true], [600, 900, true], [840, 900, false], [1440, 900, false]]) {
    await cdp.send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile });
    await cdp.send('Page.navigate', { url: `${BASE}/` });
    await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 5`, { label: 'results' });
    await sleep(700);
    const m = await cdp.eval(MEASURE);
    const clipped = m.items?.filter((i) => i.right > m.box.right + 1).length ?? 0;
    console.log(`\n${w}×${h}  box ${m.box.w}×${m.box.h}  scrollW ${m.scrollW} clientW ${m.clientW} overflowX ${m.overflowX} gap ${m.gap} pageOverflow ${m.pageOverflow} clippedItems ${clipped}`);
    for (const i of m.items ?? []) console.log(`   ${String(i.term).padEnd(22)} w=${String(i.w).padStart(4)}  [${i.left}, ${i.right}]${i.right > m.box.right + 1 ? '   <-- outside' : ''}`);
  }
} finally {
  await close();
}

