arguments.content:
import { launch, sleep } from './cdp.mjs';
const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const { cdp, close } = await launch({ port: 9350 });
try {
  for (const [w, h, name] of [[320, 900, 'facts-320'], [390, 900, 'facts-390'], [480, 900, 'facts-480']]) {
    await cdp.send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: true });
    await cdp.send('Page.navigate', { url: `${BASE}/` });
    await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 5`, { label: 'results' });
    await sleep(800);
    const { data } = await cdp.send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    const fs = await import('node:fs/promises');
    await fs.writeFile(`/tmp/probe/${name}.png`, Buffer.from(data, 'base64'));
    const m = await cdp.eval(`(() => { const map = document.querySelector('#map')?.getBoundingClientRect(); const facts = document.querySelector('#intro-facts')?.getBoundingClientRect(); return { mapTop: Math.round(map?.top ?? -1), factsH: Math.round(facts?.height ?? -1), factsBottom: Math.round(facts?.bottom ?? -1), mapVisible: Math.max(0, Math.round(Math.min(window.innerHeight, map?.bottom ?? 0) - Math.max(0, map?.top ?? 0))) }; })()`);
    console.log(`${w}px:`, JSON.stringify(m));
  }
} finally {
  await close();
}

